CREATE OR REPLACE FUNCTION public.admin_adjust_wallet(p_user_id uuid, p_amount numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor  uuid;
  v_cap    numeric;
  v_wallet RECORD;
  v_before numeric;
  v_after  numeric;
  v_txn    uuid;
  v_email  text;
BEGIN
  v_actor := public.assert_admin();

  IF p_reason IS NULL OR length(btrim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'A reason of at least 5 characters is required' USING ERRCODE = 'KS464';
  END IF;

  IF p_amount IS NULL OR p_amount = 0 THEN
    RAISE EXCEPTION 'Amount must be non-zero' USING ERRCODE = 'KS466';
  END IF;

  SELECT COALESCE(NULLIF(config_value,'')::numeric, 50) INTO v_cap
  FROM public.system_configs WHERE config_key = 'ADMIN_WALLET_ADJUST_MAX_USD';
  v_cap := COALESCE(v_cap, 50);

  IF abs(p_amount) > v_cap THEN
    RAISE EXCEPTION 'Adjustment of % exceeds the % USD support limit', p_amount, v_cap
      USING ERRCODE = 'KS466';
  END IF;

  IF p_user_id = v_actor THEN
    RAISE EXCEPTION 'You cannot adjust your own wallet' USING ERRCODE = 'KS466';
  END IF;

  SELECT * INTO v_wallet FROM public.wallets WHERE user_id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Wallet not found for user %', p_user_id USING ERRCODE = 'KS461';
  END IF;

  v_before := v_wallet.balance;
  v_after  := v_before + round(p_amount, 2);

  IF v_after < 0 THEN
    RAISE EXCEPTION 'That would take the balance to %, below zero', v_after USING ERRCODE = 'KS466';
  END IF;

  UPDATE public.wallets SET balance = v_after WHERE id = v_wallet.id;

  SELECT email INTO v_email FROM public.profiles WHERE id = v_actor;

  -- Positive and negative both store a positive amount (the CHECK requires it);
  -- direction is carried by balance_before/balance_after, as every other debit
  -- in this ledger already does.
  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, status, metadata
  ) VALUES (
    v_wallet.id, p_user_id, 'admin_adjustment', abs(round(p_amount, 2)), v_before, v_after,
    CASE WHEN p_amount > 0 THEN 'Support credit: ' ELSE 'Support correction: ' END || left(btrim(p_reason), 160),
    'adminadj_' || replace(gen_random_uuid()::text, '-', ''),
    'completed',
    jsonb_build_object('adjusted_by', v_actor::text, 'adjusted_by_email', v_email,
                       'direction', CASE WHEN p_amount > 0 THEN 'credit' ELSE 'debit' END,
                       'reason', btrim(p_reason))
  ) RETURNING id INTO v_txn;

  PERFORM public.admin_log('wallet.adjust', 'user', p_user_id::text,
    jsonb_build_object('balance', v_before),
    jsonb_build_object('balance', v_after, 'amount', p_amount, 'txn_id', v_txn),
    btrim(p_reason));

  INSERT INTO public.notifications (user_id, category, title, body)
  VALUES (p_user_id, 'wallet_credit',
          CASE WHEN p_amount > 0 THEN 'Credit added to your wallet' ELSE 'Your wallet balance was corrected' END,
          'Support adjusted your balance by ' ||
          CASE WHEN p_amount > 0 THEN '+' ELSE '-' END || '$' || to_char(abs(round(p_amount,2)),'FM999999990.00') ||
          '. New balance $' || to_char(v_after,'FM999999990.00') || '.');

  RETURN jsonb_build_object('success', true, 'balance_before', v_before,
                            'balance_after', v_after, 'transaction_id', v_txn);
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_admin()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_raw   text;
  v_role  text;
  v_uid   uuid;
BEGIN
  v_raw := current_setting('request.jwt.claims', true);
  IF v_raw IS NOT NULL AND v_raw <> '' THEN
    v_role := (v_raw::jsonb) ->> 'role';
  END IF;

  IF v_role = 'service_role' THEN
    RETURN NULL;
  END IF;

  v_uid := auth.uid();

  IF v_uid IS NULL
     OR NOT public.is_power_user(v_uid)
     OR public.is_user_suspended() THEN
    RAISE EXCEPTION 'Admin access required'
      USING ERRCODE = 'KS460',
            HINT = 'This action needs a power-user session.';
  END IF;

  RETURN v_uid;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_topup_fees()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_line_tier       TEXT := 'free';
  v_entitlement     JSONB;
  v_app_fee         NUMERIC;
  v_msg_fee         NUMERIC := 0.00;
  v_msg_fee_key     TEXT;
  pm                RECORD;
BEGIN
  IF NEW.payment_gateway_code IS NOT NULL AND NEW.base_cost_usd IS NOT NULL THEN
    SELECT * INTO pm FROM public.payment_gateways WHERE code = NEW.payment_gateway_code;

    IF FOUND THEN
      -- Resolve line tier
      IF NEW.sim_line_id IS NOT NULL THEN
        v_entitlement := public.resolve_line_entitlement(NEW.sim_line_id);
        v_line_tier := COALESCE(v_entitlement->>'effective_tier', 'free');
      END IF;

      -- Resolve app fee from app_fee_rules
      v_app_fee := public.resolve_app_fee('refills', v_line_tier, NEW.base_cost_usd);

      -- Fallback if no published rule existed
      IF v_app_fee IS NULL OR v_app_fee = 0 THEN
        v_app_fee := round(greatest(NEW.base_cost_usd * 0.03, 0.03), 2);
      END IF;

      -- Offline messaging fees if applicable
      IF NEW.refill_channel IS NOT NULL THEN
        v_msg_fee_key := CASE NEW.refill_channel
          WHEN 'whatsapp'    THEN 'OFFLINE_WHATSAPP_MESSAGE_FEE_USD'
          WHEN 'sms'         THEN 'OFFLINE_SMS_MESSAGE_FEE_USD'
          WHEN 'missed_call' THEN 'OFFLINE_MISSED_CALL_FEE_USD'
        END;
        BEGIN
          SELECT config_value::numeric INTO v_msg_fee
          FROM public.system_configs
          WHERE config_key = v_msg_fee_key;
        EXCEPTION WHEN others THEN
          v_msg_fee := 0;
        END;
        v_msg_fee := coalesce(v_msg_fee, 0);
      END IF;

      NEW.app_fee_usd := v_app_fee;
      NEW.amount := round(NEW.base_cost_usd + v_app_fee + v_msg_fee, 2);

      -- Fee calculation must preserve an explicit customer spending limit.
      IF NEW.max_authorized_usd IS NULL THEN
        NEW.max_authorized_usd := NEW.amount;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.capture_wallet_hold(p_hold_id uuid, p_txn_type text DEFAULT 'topup_debit'::text, p_description text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_hold RECORD;
  v_wallet RECORD;
  v_balance_after NUMERIC;
  v_txn_id UUID;
  v_alloc RECORD;
BEGIN
  -- Lock hold
  SELECT * INTO v_hold
  FROM public.wallet_holds
  WHERE id = p_hold_id
  FOR UPDATE;

  IF v_hold.id IS NULL THEN
    RAISE EXCEPTION 'Hold not found: %', p_hold_id;
  END IF;

  IF v_hold.status = 'captured' THEN
    -- Idempotent retry: return existing transaction if recorded in metadata
    SELECT id INTO v_txn_id
    FROM public.wallet_transactions
    WHERE reference_id = 'hold_' || p_hold_id::text;
    IF v_txn_id IS NOT NULL THEN
      RETURN v_txn_id;
    END IF;
  END IF;

  IF v_hold.status != 'active' THEN
    RAISE EXCEPTION 'Cannot capture hold in status: %', v_hold.status;
  END IF;

  -- Lock wallet
  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE id = v_hold.wallet_id
  FOR UPDATE;

  IF v_wallet.balance < v_hold.amount THEN
    RAISE EXCEPTION 'Invariant violation: wallet balance % is less than hold amount %', v_wallet.balance, v_hold.amount;
  END IF;

  v_balance_after := v_wallet.balance - v_hold.amount;

  -- Update wallet balance
  UPDATE public.wallets
  SET balance = v_balance_after,
      total_spent = total_spent + v_hold.amount,
      updated_at = now()
  WHERE id = v_wallet.id;

  -- Update allocated lots (consume remaining_amount)
  FOR v_alloc IN
    SELECT * FROM public.wallet_hold_allocations
    WHERE hold_id = p_hold_id
  LOOP
    UPDATE public.wallet_funding_lots
    SET remaining_amount = remaining_amount - v_alloc.amount,
        status = CASE WHEN remaining_amount - v_alloc.amount = 0 THEN 'fully_consumed' ELSE status END,
        updated_at = now()
    WHERE id = v_alloc.lot_id;
  END LOOP;

  -- Mark hold captured
  UPDATE public.wallet_holds
  SET status = 'captured',
      captured_at = now(),
      updated_at = now()
  WHERE id = p_hold_id;

  -- Record ledger transaction
  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, status, metadata, created_at
  ) VALUES (
    v_wallet.id, v_hold.user_id, p_txn_type, v_hold.amount, v_wallet.balance, v_balance_after,
    COALESCE(p_description, 'Purchase completed'),
    'hold_' || p_hold_id::text,
    'completed',
    jsonb_build_object('hold_id', p_hold_id, 'order_type', v_hold.order_type, 'order_reference_id', v_hold.order_reference_id) || COALESCE(p_metadata, '{}'::jsonb),
    now()
  ) RETURNING id INTO v_txn_id;

  RETURN v_txn_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.credit_wallet_for_deposit(p_user_id uuid, p_amount numeric, p_description text DEFAULT 'Wallet deposit'::text, p_reference_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_wallet_id UUID;
  v_balance_before NUMERIC;
  v_balance_after NUMERIC;
  v_txn_id UUID;
  v_order_id TEXT;
  v_capture_id TEXT;
  v_origin TEXT := 'paypal_deposit';
  v_is_refundable BOOLEAN := true;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Deposit amount must be positive, got %', p_amount;
  END IF;

  SELECT id, balance INTO v_wallet_id, v_balance_before
  FROM public.wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    INSERT INTO public.wallets (
      user_id, balance, currency, auto_fund_enabled, total_deposited, total_spent
    ) VALUES (
      p_user_id, p_amount, 'USD', false, p_amount, 0.00
    ) RETURNING id, balance - p_amount INTO v_wallet_id, v_balance_before;
    v_balance_after := p_amount;
  ELSE
    v_balance_after := v_balance_before + p_amount;
    UPDATE public.wallets
    SET balance = v_balance_after,
        total_deposited = total_deposited + p_amount,
        updated_at = now()
    WHERE id = v_wallet_id;
  END IF;

  -- Record transaction
  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, status, metadata, created_at
  ) VALUES (
    v_wallet_id, p_user_id, 'deposit', p_amount, v_balance_before, v_balance_after,
    p_description, p_reference_id, 'completed', p_metadata, now()
  ) RETURNING id INTO v_txn_id;

  -- Extract order/capture ID from metadata if present
  IF p_metadata IS NOT NULL THEN
    v_order_id := p_metadata->>'order_id';
    v_capture_id := p_metadata->>'paypal_capture_id';
  END IF;
  IF v_capture_id IS NULL AND p_reference_id LIKE 'paypal_%' THEN
    v_capture_id := replace(p_reference_id, 'paypal_', '');
  END IF;

  -- Record funding source lot
  INSERT INTO public.wallet_funding_lots (
    wallet_id, user_id, origin_type, original_reference_id, original_order_id,
    currency, funded_amount, remaining_amount, is_refundable, refund_deadline, status, created_at
  ) VALUES (
    v_wallet_id, p_user_id, v_origin, COALESCE(v_capture_id, p_reference_id), v_order_id,
    'USD', p_amount, p_amount, v_is_refundable, now() + interval '180 days', 'active', now()
  ) ON CONFLICT (user_id, original_reference_id) WHERE original_reference_id IS NOT NULL
  DO NOTHING;

  RETURN v_txn_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.credit_wallet_for_refund(p_user_id uuid, p_amount numeric, p_reference_id text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_sim_line_id uuid DEFAULT NULL::uuid, p_type text DEFAULT 'refund'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_raw_claims TEXT;
  v_jwt_role TEXT;
  v_wallet_id UUID;
  v_balance_before NUMERIC;
  v_balance_after NUMERIC;
  v_txn_id UUID;
BEGIN
  -- Layer 2: refuse anything that reached us over PostgREST as a non-service role.
  v_raw_claims := current_setting('request.jwt.claims', true);
  IF v_raw_claims IS NOT NULL AND v_raw_claims <> '' THEN
    v_jwt_role := (v_raw_claims::jsonb) ->> 'role';
    IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
      RAISE EXCEPTION 'credit_wallet_for_refund is not callable by role %', COALESCE(v_jwt_role, '<none>')
        USING ERRCODE = 'KS403';
    END IF;
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Refund amount must be positive, got %', p_amount;
  END IF;

  SELECT id, balance INTO v_wallet_id, v_balance_before
  FROM public.wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found for user %', p_user_id;
  END IF;

  v_balance_after := v_balance_before + p_amount;

  UPDATE public.wallets
  SET balance = v_balance_after,
      total_spent = GREATEST(0, total_spent - p_amount)
  WHERE id = v_wallet_id;

  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, sim_line_id, status
  ) VALUES (
    v_wallet_id, p_user_id, COALESCE(p_type, 'refund'), p_amount, v_balance_before, v_balance_after,
    p_description, p_reference_id, p_sim_line_id, 'completed'
  ) RETURNING id INTO v_txn_id;

  RETURN v_txn_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.debit_wallet_for_call(p_user_id uuid, p_call_id uuid, p_amount numeric, p_description text DEFAULT 'International Call'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_wallet_id UUID;
  v_balance_before NUMERIC;
  v_balance_after NUMERIC;
  v_txn_id UUID;
  v_ref_id TEXT;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN NULL;
  END IF;

  v_ref_id := 'call_' || p_call_id::text;

  -- Check if already debited for this call (idempotency)
  SELECT id INTO v_txn_id
  FROM public.wallet_transactions
  WHERE reference_id = v_ref_id
  LIMIT 1;

  IF v_txn_id IS NOT NULL THEN
    RETURN v_txn_id;
  END IF;

  -- Lock wallet
  SELECT id, balance INTO v_wallet_id, v_balance_before
  FROM public.wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found for user %', p_user_id;
  END IF;

  -- Debit allows balance to go to 0 or even small overdraft if call duration exceeded balance
  v_balance_after := GREATEST(0.00, v_balance_before - p_amount);

  UPDATE public.wallets
  SET balance = v_balance_after,
      total_spent = total_spent + p_amount
  WHERE id = v_wallet_id;

  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, status
  ) VALUES (
    v_wallet_id, p_user_id, 'call_debit', p_amount, v_balance_before, v_balance_after,
    p_description, v_ref_id, 'completed'
  ) RETURNING id INTO v_txn_id;

  -- Link transaction to call record
  UPDATE public.call_records
  SET wallet_txn_id = v_txn_id,
      total_cost_usd = p_amount,
      updated_at = NOW()
  WHERE id = p_call_id;

  RETURN v_txn_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.debit_wallet_for_topup(p_user_id uuid, p_sim_line_id uuid, p_amount numeric, p_description text DEFAULT 'SIM top-up'::text, p_reference_id text DEFAULT NULL::text, p_txn_type text DEFAULT 'topup_debit'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_raw_claims     TEXT;
  v_jwt_role       TEXT;
  v_ctx            TEXT;
  v_wallet_id      UUID;
  v_balance_before NUMERIC;
  v_balance_after  NUMERIC;
  v_txn_id         UUID;
  v_exec_id        UUID;
  v_acting         UUID;
  v_chk            RECORD;
  v_metadata       JSONB := '{}'::jsonb;
BEGIN
  v_raw_claims := current_setting('request.jwt.claims', true);
  IF v_raw_claims IS NOT NULL AND v_raw_claims <> '' THEN
    v_jwt_role := (v_raw_claims::jsonb) ->> 'role';
    IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
      GET DIAGNOSTICS v_ctx = PG_CONTEXT;
      IF coalesce(array_length(string_to_array(v_ctx, E'\n'), 1), 1) < 2 THEN
        RAISE EXCEPTION 'debit_wallet_for_topup is not directly callable by role %', COALESCE(v_jwt_role, '<none>')
          USING ERRCODE = 'KS403';
      END IF;
    END IF;
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Debit amount must be positive, got %', p_amount;
  END IF;

  IF p_reference_id ~ '^exec_[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    v_exec_id := substring(p_reference_id FROM 6)::uuid;

    SELECT te.acting_user_id INTO v_acting
    FROM public.topup_executions te
    WHERE te.id = v_exec_id;
  END IF;

  IF v_acting IS NOT NULL AND v_acting <> p_user_id THEN
    SELECT * INTO v_chk
    FROM public.household_spend_check(p_user_id, v_acting, p_amount, v_exec_id);

    IF NOT v_chk.allowed THEN
      RAISE EXCEPTION 'HOUSEHOLD_CAP:%:%:%:%',
        v_chk.reason, v_chk.monthly_cap, v_chk.spent_mtd, v_chk.remaining_usd
        USING ERRCODE = 'KS402';
    END IF;

    v_metadata := jsonb_build_object(
      'spent_by',        v_acting::text,
      'spent_for_owner', p_user_id::text,
      'household',       true
    );
  END IF;

  SELECT id, balance INTO v_wallet_id, v_balance_before
  FROM public.wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found for user %', p_user_id;
  END IF;

  IF v_balance_before < p_amount THEN
    RAISE EXCEPTION 'Insufficient wallet balance. Have: %, Need: %', v_balance_before, p_amount;
  END IF;

  v_balance_after := v_balance_before - p_amount;

  UPDATE public.wallets
  SET balance = v_balance_after,
      total_spent = total_spent + p_amount
  WHERE id = v_wallet_id;

  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, sim_line_id, status, metadata
  ) VALUES (
    v_wallet_id, p_user_id, COALESCE(p_txn_type, 'topup_debit'), p_amount, v_balance_before, v_balance_after,
    p_description, p_reference_id, p_sim_line_id, 'completed', v_metadata
  ) RETURNING id INTO v_txn_id;

  RETURN v_txn_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_wallet_v2(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_wallet RECORD;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'User ID cannot be null';
  END IF;

  SELECT * INTO v_wallet FROM public.wallets WHERE user_id = p_user_id FOR UPDATE;

  IF v_wallet.id IS NULL THEN
    INSERT INTO public.wallets (
      user_id, balance, currency, auto_fund_enabled, total_deposited, total_spent
    ) VALUES (
      p_user_id, 0.00, 'USD', false, 0.00, 0.00
    ) RETURNING * INTO v_wallet;
  END IF;

  RETURN jsonb_build_object(
    'id', v_wallet.id,
    'user_id', v_wallet.user_id,
    'balance', v_wallet.balance,
    'currency', v_wallet.currency
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_sim_setup_order(p_order_id uuid, p_provider_tx_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order            public.sim_setup_orders%ROWTYPE;
  v_line_id          UUID;
  v_rule             public.carrier_rules%ROWTYPE;
  v_sched_id         UUID;
  v_interval_days    INTEGER;
  v_offer_id         TEXT := NULL;
  v_offer_value      BIGINT := NULL;
  v_provider         TEXT := NULL;
  v_intent_kind      TEXT := 'exact_airtime';
  v_target_local_val NUMERIC := NULL;
  v_target_local_cur TEXT := NULL;
  v_fee_rule_ver     INTEGER := NULL;
BEGIN
  SELECT * INTO v_order
  FROM public.sim_setup_orders
  WHERE id = p_order_id FOR UPDATE;

  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Setup order not found: %', p_order_id;
  END IF;

  IF v_order.status = 'active' THEN
    RETURN jsonb_build_object('success', true, 'status', 'active', 'already_captured', true);
  END IF;

  -- 1. Capture annual fee hold
  IF v_order.annual_fee_hold_id IS NOT NULL THEN
    PERFORM public.capture_wallet_hold(
      v_order.annual_fee_hold_id,
      'plan_fee_debit',
      'Annual Protection Fee (' || v_order.plan || ')',
      jsonb_build_object('setup_order_id', p_order_id, 'plan', v_order.plan, 'order_type', 'plan_fee')
    );
  END IF;

  -- 2. Capture initial refill hold
  IF v_order.first_refill_hold_id IS NOT NULL THEN
    PERFORM public.capture_wallet_hold(
      v_order.first_refill_hold_id,
      'topup_debit',
      'Initial SIM Recharge (' || v_order.phone_number || ')',
      jsonb_build_object('setup_order_id', p_order_id, 'provider_tx_id', p_provider_tx_id, 'order_type', 'setup_refill')
    );
  END IF;

  v_line_id := v_order.sim_line_id;
  IF v_line_id IS NULL THEN
    SELECT id INTO v_line_id
    FROM public.sim_lines
    WHERE user_id = v_order.user_id AND phone_number = v_order.phone_number
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_line_id IS NOT NULL THEN
      UPDATE public.sim_setup_orders
      SET sim_line_id = v_line_id, updated_at = now()
      WHERE id = p_order_id;
    ELSE
      RAISE EXCEPTION 'Cannot activate setup order without an associated sim_line_id: %', p_order_id;
    END IF;
  END IF;

  -- 3. Activate SIM Line (keep unverified until user performs real live verification)
  UPDATE public.sim_lines
  SET status = 'active',
      plan_type = v_order.plan,
      protection_tier = CASE WHEN v_order.plan = 'free' THEN 'basic' ELSE v_order.plan END,
      plan_expires_at = now() + INTERVAL '365 days',
      last_topup_at = CASE WHEN v_order.plan = 'premium' THEN now() ELSE last_topup_at END,
      carrier_status = 'active',
      updated_at = now()
  WHERE id = v_line_id;

  -- 4. Record plan payment
  IF v_order.annual_fee_usd > 0 THEN
    INSERT INTO public.plan_payments (
      user_id, sim_line_id, capture_id, order_id, kind, gross_usd, net_usd,
      paypal_fee_usd, metadata, created_at
    ) VALUES (
      v_order.user_id,
      v_line_id,
      COALESCE(v_order.annual_fee_hold_id::text, 'setup_' || p_order_id::text),
      p_order_id::text,
      'plan',
      v_order.annual_fee_usd,
      v_order.annual_fee_usd,
      0.00,
      jsonb_build_object('billing_model', 'pay_per_refill', 'plan', v_order.plan, 'setup_order_id', p_order_id),
      now()
    );
  END IF;

  -- 5. Create Schedules
  IF v_order.plan IN ('standard', 'premium', 'free') THEN
    INSERT INTO public.scheduled_topups (
      user_id, sim_line_id, schedule_type, status, is_active,
      target_channel, interval_days, next_execution_at,
      created_at, updated_at
    ) VALUES (
      v_order.user_id,
      v_line_id,
      'notify',
      'active',
      true,
      'in_app',
      30,
      now() + INTERVAL '30 days',
      now(),
      now()
    )
    ON CONFLICT DO NOTHING;
  END IF;

  IF v_order.plan = 'premium' THEN
    SELECT * INTO v_rule
    FROM public.carrier_rules
    WHERE carrier_id = (SELECT carrier_id FROM public.sim_lines WHERE id = v_line_id)
    LIMIT 1;

    v_interval_days := COALESCE(
      v_rule.refill_interval_days_override,
      GREATEST(1, COALESCE(v_rule.inactivity_limit_days, 90) - COALESCE(v_rule.grace_period_days, 3))
    );

    IF v_rule.id IS NOT NULL THEN
      v_offer_id := v_rule.offer_id;
      v_offer_value := v_rule.offer_value;
      v_intent_kind := COALESCE(v_rule.activity_requirement, 'exact_airtime');
      v_target_local_val := v_rule.minimum_topup_amount;
      v_target_local_cur := v_rule.inapp_pricing_currency;
    END IF;

    SELECT provider INTO v_provider
    FROM public.carrier_provider_map
    WHERE carrier_id = (SELECT carrier_id FROM public.sim_lines WHERE id = v_line_id)
      AND is_enabled = true
    ORDER BY priority ASC
    LIMIT 1;

    INSERT INTO public.scheduled_topups (
      user_id, sim_line_id, schedule_type, status, is_active,
      amount, target_channel, interval_days, next_execution_at,
      metadata, created_at, updated_at
    ) VALUES (
      v_order.user_id,
      v_line_id,
      'refill_mini',
      'active',
      true,
      COALESCE(v_rule.inapp_pricing, 5.00),
      'auto',
      v_interval_days,
      now() + (v_interval_days || ' days')::INTERVAL,
      jsonb_build_object(
        'carrier_rule_id', v_rule.id,
        'offer_id', v_offer_id,
        'offer_value', v_offer_value,
        'provider', v_provider,
        'intent_kind', v_intent_kind,
        'target_local_value', v_target_local_val,
        'target_local_currency', v_target_local_cur,
        'fee_rule_version', v_fee_rule_ver,
        'auto_configured', true
      ),
      now(),
      now()
    )
    RETURNING id INTO v_sched_id;

    IF v_sched_id IS NOT NULL THEN
      PERFORM public.queue_premium_refill_executions(
        v_line_id,
        v_sched_id,
        now() + INTERVAL '365 days'
      );
    END IF;
  END IF;

  -- 6. Mark setup order active
  UPDATE public.sim_setup_orders
  SET status = 'active',
      updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'status', 'active',
    'sim_line_id', v_line_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_sim_setup_order(p_order_id uuid, p_sim_line_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id        UUID := auth.uid();
  v_order          RECORD;
  v_execution      RECORD;
  v_target_line_id UUID;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;

  SELECT * INTO v_order
  FROM public.sim_setup_orders
  WHERE id = p_order_id AND user_id = v_user_id FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;

  -- If order doesn't have sim_line_id linked yet, resolve it
  IF v_order.sim_line_id IS NULL THEN
    v_target_line_id := p_sim_line_id;

    -- Fallback: resolve from user's sim_lines matching phone_number
    IF v_target_line_id IS NULL THEN
      SELECT id INTO v_target_line_id
      FROM public.sim_lines
      WHERE user_id = v_user_id AND phone_number = v_order.phone_number
      ORDER BY created_at DESC
      LIMIT 1;
    END IF;

    IF v_target_line_id IS NOT NULL THEN
      -- Validate ownership
      IF NOT EXISTS (SELECT 1 FROM public.sim_lines WHERE id = v_target_line_id AND user_id = v_user_id) THEN
        RAISE EXCEPTION 'SIM line not found or unauthorized';
      END IF;

      UPDATE public.sim_setup_orders
      SET sim_line_id = v_target_line_id,
          updated_at = now()
      WHERE id = p_order_id;

      SELECT * INTO v_order
      FROM public.sim_setup_orders
      WHERE id = p_order_id;
    END IF;
  END IF;

  IF v_order.status = 'active' THEN
    RETURN jsonb_build_object('success', true, 'status', 'active', 'plan', v_order.plan);
  END IF;

  IF v_order.status = 'failed' THEN
    RETURN jsonb_build_object('success', false, 'status', 'failed', 'reason', v_order.failure_reason);
  END IF;

  -- For Standard: can capture immediately if holds are reserved
  IF v_order.plan = 'standard' THEN
    RETURN public.capture_sim_setup_holds(p_order_id);
  END IF;

  -- For Premium: check execution outcome
  SELECT * INTO v_execution
  FROM public.topup_executions
  WHERE wallet_hold_id = v_order.first_refill_hold_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'status', 'dispatching', 'pending', true);
  END IF;

  IF v_execution.status = 'success' THEN
    RETURN public.capture_sim_setup_holds(p_order_id, v_execution.reloadly_transaction_id);
  ELSIF v_execution.status IN ('failed', 'cancelled') THEN
    RETURN public.release_sim_setup_holds(p_order_id, COALESCE(v_execution.failure_reason, 'Initial recharge failed'));
  ELSE
    -- Still routing / processing
    RETURN jsonb_build_object('success', false, 'status', 'dispatching', 'pending', true);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.format_sim_line_tier_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
