$function$

CREATE OR REPLACE FUNCTION public.get_call_rate_for_number(p_phone_number text, p_user_id uuid DEFAULT auth.uid())
 RETURNS TABLE(id uuid, country_code text, country_name text, phone_prefix text, rate_per_minute_usd numeric, cost_per_minute_usd numeric, connection_fee_usd numeric, billing_increment_seconds integer, account_tier text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_clean_number TEXT;
  v_tier         TEXT;
  v_rate         RECORD;
  v_effective    NUMERIC;
  v_fee          NUMERIC;
BEGIN
  -- 1. Resolve Halo tier for this account
  v_tier := public.resolve_account_commerce_benefit(p_user_id);

  -- 2. Normalize number format
  v_clean_number := regexp_replace(p_phone_number, '[^0-9+]', '', 'g');
  IF NOT (v_clean_number LIKE '+%') THEN
    v_clean_number := '+' || v_clean_number;
  END IF;

  SELECT
    cr.id,
    cr.country_code,
    cr.country_name,
    cr.phone_prefix,
    cr.rate_per_minute_usd,
    cr.cost_per_minute_usd,
    0.00::NUMERIC AS connection_fee_usd, -- Strictly $0 connection fee per C12
    cr.billing_increment_seconds
  INTO v_rate
  FROM public.call_rates cr
  WHERE cr.is_active = TRUE
    AND v_clean_number LIKE (cr.phone_prefix || '%')
  ORDER BY length(cr.phone_prefix) DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- 3. Calculate effective rate per minute with intelcallfee app fee rule
  IF v_rate.cost_per_minute_usd IS NOT NULL AND v_rate.cost_per_minute_usd > 0 THEN
    v_fee := public.resolve_app_fee('intelcallfee', v_tier, v_rate.cost_per_minute_usd);
    IF v_fee IS NULL THEN
      -- Fallback to default draft percentages if no rule in table
      v_fee := CASE v_tier
        WHEN 'premium'  THEN round(v_rate.cost_per_minute_usd * 0.05, 4)
        WHEN 'standard' THEN round(v_rate.cost_per_minute_usd * 0.10, 4)
        ELSE round(v_rate.cost_per_minute_usd * 0.15, 4)
      END;
    END IF;
    v_effective := round(v_rate.cost_per_minute_usd + v_fee, 4);
  ELSE
    v_effective := v_rate.rate_per_minute_usd;
  END IF;

  RETURN QUERY
  SELECT
    v_rate.id,
    v_rate.country_code,
    v_rate.country_name,
    v_rate.phone_prefix,
    v_effective AS rate_per_minute_usd,
    v_rate.cost_per_minute_usd,
    0.00::NUMERIC AS connection_fee_usd,
    v_rate.billing_increment_seconds,
    v_tier AS account_tier;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_wallet_summary(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_wallet RECORD;
  v_held_amount NUMERIC := 0.00;
  v_available_amount NUMERIC := 0.00;
  v_refundable_amount NUMERIC := 0.00;
  v_promotional_amount NUMERIC := 0.00;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'User ID cannot be null';
  END IF;

  -- Caller must be self or service role / admin
  IF auth.uid() IS NOT NULL AND auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Access denied: cannot view another user wallet summary' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_wallet FROM public.wallets WHERE user_id = p_user_id;

  IF v_wallet.id IS NULL THEN
    -- Return default zero summary
    RETURN jsonb_build_object(
      'wallet_id', null,
      'posted_balance', 0.00,
      'held_amount', 0.00,
      'available_balance', 0.00,
      'refundable_balance', 0.00,
      'promotional_balance', 0.00,
      'currency', 'USD'
    );
  END IF;

  -- Calculate active holds
  SELECT COALESCE(SUM(amount), 0.00) INTO v_held_amount
  FROM public.wallet_holds
  WHERE user_id = p_user_id AND status = 'active';

  v_available_amount := GREATEST(0.00, v_wallet.balance - v_held_amount);

  -- Calculate refundable balance (active paid deposits within deadline)
  SELECT COALESCE(SUM(remaining_amount), 0.00) INTO v_refundable_amount
  FROM public.wallet_funding_lots
  WHERE user_id = p_user_id 
    AND status = 'active'
    AND is_refundable = true
    AND (refund_deadline IS NULL OR refund_deadline > now());

  -- Ensure refundable does not exceed available balance
  v_refundable_amount := LEAST(v_refundable_amount, v_available_amount);

  -- Calculate promotional / gift balance
  SELECT COALESCE(SUM(remaining_amount), 0.00) INTO v_promotional_amount
  FROM public.wallet_funding_lots
  WHERE user_id = p_user_id
    AND status = 'active'
    AND origin_type IN ('promotional', 'unverified_legacy', 'gift_received');

  RETURN jsonb_build_object(
    'wallet_id', v_wallet.id,
    'posted_balance', v_wallet.balance,
    'held_amount', v_held_amount,
    'available_balance', v_available_amount,
    'refundable_balance', v_refundable_amount,
    'promotional_balance', v_promotional_amount,
    'currency', v_wallet.currency
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.has_paid_premium_entitlement(p_sim_line_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_line   RECORD;
  v_window timestamptz;
BEGIN
  SELECT sl.user_id, sl.plan_type, sl.plan_expires_at
  INTO v_line
  FROM public.sim_lines sl
  WHERE sl.id = p_sim_line_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF lower(coalesce(v_line.plan_type, '')) <> 'premium' THEN
    RETURN false;
  END IF;

  IF EXISTS (SELECT 1 FROM public.premium_entitlement_grandfather g
             WHERE g.sim_line_id = p_sim_line_id) THEN
    RETURN true;
  END IF;

  IF v_line.plan_expires_at IS NULL OR v_line.plan_expires_at <= now() THEN
    RETURN false;
  END IF;

  v_window := v_line.plan_expires_at - interval '366 days';

  -- Strictly require sim_line_id to match. Never accept unbound account payments.
  IF EXISTS (
    SELECT 1 FROM public.plan_payments pp
    WHERE pp.kind = 'plan'
      AND pp.sim_line_id = p_sim_line_id
      AND pp.created_at >= v_window
  ) THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.quote_wallet_refund(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_wallet RECORD;
  v_held NUMERIC := 0.00;
  v_available NUMERIC := 0.00;
  v_refundable NUMERIC := 0.00;
  v_lots JSONB := '[]'::jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'User ID cannot be null';
  END IF;

  IF auth.uid() IS NOT NULL AND auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Access denied: cannot quote refund for another user' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_wallet FROM public.wallets WHERE user_id = p_user_id;

  IF v_wallet.id IS NULL THEN
    RETURN jsonb_build_object('eligible_amount', 0.00, 'items', '[]'::jsonb);
  END IF;

  SELECT COALESCE(SUM(amount), 0.00) INTO v_held
  FROM public.wallet_holds
  WHERE user_id = p_user_id AND status = 'active';

  v_available := GREATEST(0.00, v_wallet.balance - v_held);

  -- Sum eligible refundable lots
  SELECT COALESCE(SUM(remaining_amount), 0.00) INTO v_refundable
  FROM public.wallet_funding_lots
  WHERE user_id = p_user_id
    AND is_refundable = true
    AND status = 'active'
    AND (refund_deadline IS NULL OR refund_deadline > now());

  v_refundable := LEAST(v_refundable, v_available);

  SELECT jsonb_agg(jsonb_build_object(
    'lot_id', id,
    'capture_id', original_reference_id,
    'funded_amount', funded_amount,
    'remaining_amount', remaining_amount,
    'refund_deadline', refund_deadline
  )) INTO v_lots
  FROM (
    SELECT * FROM public.wallet_funding_lots
    WHERE user_id = p_user_id
      AND is_refundable = true
      AND status = 'active'
      AND (refund_deadline IS NULL OR refund_deadline > now())
    ORDER BY created_at ASC
  ) sub;

  RETURN jsonb_build_object(
    'eligible_amount', v_refundable,
    'available_balance', v_available,
    'currency', 'USD',
    'lots', COALESCE(v_lots, '[]'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reap_stale_esim_orders()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order RECORD;
  v_reaped_refund_count integer := 0;
  v_reaped_unpaid_count integer := 0;
  v_refund_ref text;
  v_debit_amount numeric;
  v_stale_hours integer := 3;
  v_refund_type text := 'esim_purchase_refund';
BEGIN
  BEGIN
    SELECT config_value::integer INTO v_stale_hours
    FROM public.system_configs
    WHERE config_key = 'ESIM_STALE_ORDER_HOURS';
  EXCEPTION WHEN OTHERS THEN
    v_stale_hours := 3;
  END;
  IF v_stale_hours IS NULL OR v_stale_hours < 1 THEN
    v_stale_hours := 3;
  END IF;

  FOR v_order IN
    SELECT id, user_id, retail_price_usd, quantity, created_at
    FROM public.esim_orders
    WHERE status = 'pending'
      AND provider_order_ref IS NULL
      AND created_at < NOW() - (v_stale_hours || ' hours')::interval
    FOR UPDATE SKIP LOCKED
  LOOP
    v_refund_ref := 'esim_refund_' || v_order.id::text;

    IF EXISTS (
      SELECT 1 FROM public.wallet_transactions
      WHERE reference_id = v_refund_ref
        AND type = v_refund_type
    ) THEN
      CONTINUE;
    END IF;

    SELECT amount INTO v_debit_amount
    FROM public.wallet_transactions
    WHERE reference_id = 'esim_' || v_order.id::text
      AND type = 'esim_purchase_debit'
      AND status = 'completed'
    LIMIT 1;

    IF v_debit_amount IS NULL OR v_debit_amount <= 0 THEN
      UPDATE public.esim_orders
      SET status = 'failed',
          error_message = 'stale_unpaid_order_reaped',
          updated_at = NOW()
      WHERE id = v_order.id;

      INSERT INTO public.system_alerts (kind, message, details, created_at)
      VALUES (
        'stale_esim_order_unpaid',
        'Stale eSIM order ' || v_order.id::text || ' reaped but no completed wallet debit transaction was found.',
        jsonb_build_object('order_id', v_order.id, 'user_id', v_order.user_id),
        NOW()
      );

      v_reaped_unpaid_count := v_reaped_unpaid_count + 1;
    ELSE
      UPDATE public.esim_orders
      SET status = 'failed',
          error_message = 'stale_timeout_reaped',
          updated_at = NOW()
      WHERE id = v_order.id;

      PERFORM public.credit_wallet_for_refund(
        v_order.user_id,
        v_debit_amount,
        v_refund_ref,
        'Stale eSIM order auto-refund',
        NULL,
        v_refund_type
      );

      INSERT INTO public.system_alerts (kind, message, details, created_at)
      VALUES (
        'stale_esim_order_reaped',
        'Stale pending eSIM order ' || v_order.id::text || ' auto-reaped and refunded after ' || v_stale_hours || ' hours timeout.',
        jsonb_build_object(
          'order_id', v_order.id,
          'user_id', v_order.user_id,
          'amount_usd', v_debit_amount,
          'created_at', v_order.created_at
        ),
        NOW()
      );

      v_reaped_refund_count := v_reaped_refund_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'SUCCESS',
    'reaped_refund_count', v_reaped_refund_count,
    'reaped_unpaid_count', v_reaped_unpaid_count,
    'reaped_count', (v_reaped_refund_count + v_reaped_unpaid_count)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.release_wallet_hold(p_hold_id uuid, p_reason text DEFAULT 'Operation cancelled or failed'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_hold RECORD;
BEGIN
  SELECT * INTO v_hold
  FROM public.wallet_holds
  WHERE id = p_hold_id
  FOR UPDATE;

  IF v_hold.id IS NULL THEN
    RAISE EXCEPTION 'Hold not found: %', p_hold_id;
  END IF;

  IF v_hold.status = 'released' THEN
    RETURN true; -- Idempotent
  END IF;

  IF v_hold.status != 'active' THEN
    RAISE EXCEPTION 'Cannot release hold in status: %', v_hold.status;
  END IF;

  UPDATE public.wallet_holds
  SET status = 'released',
      released_at = now(),
      reason = COALESCE(p_reason, reason),
      updated_at = now()
  WHERE id = p_hold_id;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_wallet_refund(p_user_id uuid, p_amount numeric, p_reason text DEFAULT 'Customer requested refund of unused balance'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_wallet RECORD;
  v_held NUMERIC := 0.00;
  v_available NUMERIC := 0.00;
  v_refundable NUMERIC := 0.00;
  v_request_id UUID;
  v_hold_id UUID;
  v_needed NUMERIC;
  v_lot RECORD;
  v_item_amount NUMERIC;
  v_item_id UUID;
  v_item_count INTEGER := 0;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Refund amount must be positive, got %', p_amount;
  END IF;

  IF auth.uid() IS NOT NULL AND auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Access denied: cannot request refund for another user' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet.id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found for user %', p_user_id;
  END IF;

  SELECT COALESCE(SUM(amount), 0.00) INTO v_held
  FROM public.wallet_holds
  WHERE user_id = p_user_id AND status = 'active';

  v_available := v_wallet.balance - v_held;

  IF v_available < p_amount THEN
    RAISE EXCEPTION 'Requested refund amount % exceeds available balance %', p_amount, v_available;
  END IF;

  -- Check eligible refundable lots
  SELECT COALESCE(SUM(remaining_amount), 0.00) INTO v_refundable
  FROM public.wallet_funding_lots
  WHERE user_id = p_user_id
    AND is_refundable = true
    AND status = 'active'
    AND (refund_deadline IS NULL OR refund_deadline > now());

  IF v_refundable < p_amount THEN
    RAISE EXCEPTION 'Requested refund amount % exceeds eligible refundable paid deposits %', p_amount, v_refundable;
  END IF;

  -- Create refund request
  INSERT INTO public.wallet_refund_requests (
    user_id, wallet_id, requested_amount, currency, status, audit_notes, created_at
  ) VALUES (
    p_user_id, v_wallet.id, p_amount, 'USD', 'requested', p_reason, now()
  ) RETURNING id INTO v_request_id;

  -- Create hold for the refund
  INSERT INTO public.wallet_holds (
    wallet_id, user_id, order_type, order_reference_id, amount, currency,
    status, reason, created_at
  ) VALUES (
    v_wallet.id, p_user_id, 'refund_request', 'refund_' || v_request_id::text, p_amount, 'USD',
    'active', 'Reserved for refund request ' || v_request_id::text, now()
  ) RETURNING id INTO v_hold_id;

  UPDATE public.wallet_refund_requests SET hold_id = v_hold_id WHERE id = v_request_id;

  -- Allocate to specific lots and create refund items
  v_needed := p_amount;

  FOR v_lot IN
    SELECT * FROM public.wallet_funding_lots
    WHERE user_id = p_user_id
      AND is_refundable = true
      AND status = 'active'
      AND (refund_deadline IS NULL OR refund_deadline > now())
      AND remaining_amount > 0
    ORDER BY created_at ASC
    FOR UPDATE
  LOOP
    EXIT WHEN v_needed <= 0;

    v_item_amount := LEAST(v_lot.remaining_amount, v_needed);

    -- Record hold allocation
    INSERT INTO public.wallet_hold_allocations (hold_id, lot_id, amount, created_at)
    VALUES (v_hold_id, v_lot.id, v_item_amount, now());

    -- Create refund item
    INSERT INTO public.wallet_refund_items (
      refund_request_id, lot_id, provider, capture_id, amount, currency,
      idempotency_key, status, created_at
    ) VALUES (
      v_request_id, v_lot.id, 'paypal', v_lot.original_reference_id, v_item_amount, 'USD',
      'refitem_' || v_request_id::text || '_' || v_lot.id::text,
      'pending', now()
    ) RETURNING id INTO v_item_id;

    v_item_count := v_item_count + 1;
    v_needed := v_needed - v_item_amount;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'refund_request_id', v_request_id,
    'hold_id', v_hold_id,
    'amount', p_amount,
    'item_count', v_item_count
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reserve_sim_setup_holds(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id             UUID;
  v_order               RECORD;
  v_wallet              RECORD;
  v_held_amount         NUMERIC := 0.00;
  v_available           NUMERIC := 0.00;
  v_fee_hold_id         UUID;
  v_refill_hold_id      UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_order
  FROM public.sim_setup_orders
  WHERE id = p_order_id FOR UPDATE;

  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Setup order not found: %', p_order_id;
  END IF;

  IF v_order.user_id <> v_user_id THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF v_order.status = 'reserved' AND v_order.annual_fee_hold_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'status', 'reserved', 'order_id', p_order_id);
  END IF;

  IF v_order.status NOT IN ('draft', 'awaiting_funds') THEN
    RAISE EXCEPTION 'Cannot reserve holds for order in status: %', v_order.status;
  END IF;

  -- Lock wallet
  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE user_id = v_user_id FOR UPDATE;

  IF v_wallet.id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found for user';
  END IF;

  SELECT COALESCE(SUM(amount), 0.00) INTO v_held_amount
  FROM public.wallet_holds
  WHERE user_id = v_user_id AND status = 'active';

  v_available := v_wallet.balance - v_held_amount;

  IF v_available < v_order.total_charge_usd THEN
    UPDATE public.sim_setup_orders
    SET status = 'awaiting_funds', updated_at = now()
    WHERE id = p_order_id;

    RETURN jsonb_build_object(
      'success', false,
      'code', 'insufficient_funds',
      'error', 'insufficient_balance',
      'message', 'Your wallet balance cannot cover this plan. Please add funds to continue.',
      'available_balance', v_available,
      'current_balance', v_available,
      'required_balance', v_order.total_charge_usd,
      'shortfall', round(v_order.total_charge_usd - v_available, 2)
    );
  END IF;

  -- 1. Hold annual fee if > 0
  IF v_order.annual_fee_usd > 0 THEN
    v_fee_hold_id := public.reserve_wallet_funds(
      v_user_id,
      v_order.annual_fee_usd,
      'plan_fee',
      'setup_fee_' || p_order_id::text,
      'Annual KeepSIMs Protection Fee Hold',
      240
    );
  END IF;

  -- 2. Hold first refill as 'setup_refill' if > 0
  IF v_order.first_refill_cost_usd > 0 THEN
    v_refill_hold_id := public.reserve_wallet_funds(
      v_user_id,
      v_order.first_refill_cost_usd,
      'setup_refill',
      'setup_refill_' || p_order_id::text,
      'Initial SIM Setup Refill Hold',
      240
    );
  END IF;

  UPDATE public.sim_setup_orders
  SET annual_fee_hold_id = v_fee_hold_id,
      first_refill_hold_id = v_refill_hold_id,
      status = 'reserved',
      updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'status', 'reserved',
    'annual_fee_hold_id', v_fee_hold_id,
    'first_refill_hold_id', v_refill_hold_id,
    'total_charge_usd', v_order.total_charge_usd
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reserve_wallet_funds(p_user_id uuid, p_amount numeric, p_order_type text, p_order_reference_id text, p_reason text DEFAULT NULL::text, p_ttl_minutes integer DEFAULT 120)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_wallet_id UUID;
  v_balance NUMERIC;
  v_held_amount NUMERIC := 0.00;
  v_available NUMERIC := 0.00;
  v_hold_id UUID;
  v_existing_hold RECORD;
  v_needed NUMERIC;
  v_lot RECORD;
  v_alloc_amount NUMERIC;
  v_active_lot_alloc NUMERIC;
  v_available_in_lot NUMERIC;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Hold amount must be positive, got %', p_amount;
  END IF;

  IF p_order_type IS NULL OR p_order_reference_id IS NULL THEN
    RAISE EXCEPTION 'order_type and order_reference_id are required';
  END IF;

  -- Idempotency check: if active hold exists for this reference, adopt it
  SELECT * INTO v_existing_hold
  FROM public.wallet_holds
  WHERE order_type = p_order_type AND order_reference_id = p_order_reference_id;

  IF v_existing_hold.id IS NOT NULL THEN
    IF v_existing_hold.status = 'active' THEN
      -- F09: Verify user_id and amount match
      IF v_existing_hold.user_id != p_user_id THEN
        RAISE EXCEPTION 'Existing hold % belongs to user %, but requested for user %', v_existing_hold.id, v_existing_hold.user_id, p_user_id;
      END IF;
      IF v_existing_hold.amount != p_amount THEN
        RAISE EXCEPTION 'Existing hold % has amount %, but requested amount is %', v_existing_hold.id, v_existing_hold.amount, p_amount;
      END IF;
      RETURN v_existing_hold.id;
    ELSE
      RAISE EXCEPTION 'Hold for % % is already in status %', p_order_type, p_order_reference_id, v_existing_hold.status;
    END IF;
  END IF;

  -- Lock wallet
  SELECT id, balance INTO v_wallet_id, v_balance
  FROM public.wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found for user %', p_user_id;
  END IF;

  -- Calculate current active holds
  SELECT COALESCE(SUM(amount), 0.00) INTO v_held_amount
  FROM public.wallet_holds
  WHERE user_id = p_user_id AND status = 'active';

  v_available := v_balance - v_held_amount;

  IF v_available < p_amount THEN
    RAISE EXCEPTION 'Insufficient available balance. Available: %, Needed: %', v_available, p_amount;
  END IF;

  -- Create hold
  INSERT INTO public.wallet_holds (
    wallet_id, user_id, order_type, order_reference_id, amount, currency,
    status, reason, expires_at, created_at
  ) VALUES (
    v_wallet_id, p_user_id, p_order_type, p_order_reference_id, p_amount, 'USD',
    'active', p_reason, now() + (p_ttl_minutes || ' minutes')::interval, now()
  ) RETURNING id INTO v_hold_id;

  -- Allocate lots: Spend non-refundable/promotional first, then gifts, then paid deposits oldest first
  v_needed := p_amount;

  FOR v_lot IN
    SELECT * FROM public.wallet_funding_lots
    WHERE user_id = p_user_id AND status = 'active' AND remaining_amount > 0
    ORDER BY
      CASE
        WHEN origin_type IN ('promotional', 'unverified_legacy') THEN 1
        WHEN origin_type = 'gift_received' THEN 2
        ELSE 3
      END ASC,
      created_at ASC
    FOR UPDATE
  LOOP
    EXIT WHEN v_needed <= 0;

    -- Subtract any already-allocated amounts from active holds on this lot
    SELECT COALESCE(SUM(a.amount), 0.00) INTO v_active_lot_alloc
    FROM public.wallet_hold_allocations a
    JOIN public.wallet_holds h ON h.id = a.hold_id
    WHERE a.lot_id = v_lot.id AND h.status = 'active' AND h.id != v_hold_id;

    v_available_in_lot := v_lot.remaining_amount - v_active_lot_alloc;

    IF v_available_in_lot > 0 THEN
      v_alloc_amount := LEAST(v_available_in_lot, v_needed);

      INSERT INTO public.wallet_hold_allocations (hold_id, lot_id, amount, created_at)
      VALUES (v_hold_id, v_lot.id, v_alloc_amount, now());

      v_needed := v_needed - v_alloc_amount;
    END IF;
  END LOOP;

  -- Invariant check: Assert that the entire requested amount was successfully allocated
  IF v_needed > 0 THEN
    RAISE EXCEPTION 'Invariant violation: unable to allocate full amount from active lots. Short by %', v_needed;
  END IF;

  RETURN v_hold_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_account_commerce_benefit(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_highest_tier   TEXT := 'free';
  v_line           RECORD;
  v_entitlement    JSONB;
  v_tier           TEXT;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN 'free';
  END IF;

  FOR v_line IN
    SELECT id FROM public.sim_lines
    WHERE user_id = p_user_id
      AND status = 'active'
  LOOP
    v_entitlement := public.resolve_line_entitlement(v_line.id);
    v_tier := v_entitlement->>'effective_tier';

    IF v_tier = 'premium' THEN
      RETURN 'premium';
    ELSIF v_tier = 'standard' AND v_highest_tier <> 'premium' THEN
      v_highest_tier := 'standard';
    END IF;
  END LOOP;

  RETURN v_highest_tier;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_app_fee(p_item text, p_tier text, p_base_amount numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule RECORD;
  v_pct  NUMERIC;
  v_min  NUMERIC;
  v_fee  NUMERIC;
  v_tier TEXT := lower(coalesce(p_tier, 'free'));
BEGIN
  IF p_base_amount IS NULL OR p_base_amount <= 0 THEN
    RETURN 0.00;
  END IF;

  -- 1. Look for active published rule
  SELECT * INTO v_rule
  FROM public.app_fee_rules
  WHERE appfees_item = p_item
    AND status = 'published'
    AND (effective_from IS NULL OR effective_from <= now())
    AND (effective_to IS NULL OR effective_to > now())
  ORDER BY version DESC
  LIMIT 1;

  -- 2. Fallback to latest draft rule if no published rule exists
  IF NOT FOUND THEN
    SELECT * INTO v_rule
    FROM public.app_fee_rules
    WHERE appfees_item = p_item
    ORDER BY version DESC
    LIMIT 1;
  END IF;

  IF NOT FOUND THEN
    RETURN 0.00;
  END IF;

  IF v_tier = 'premium' THEN
    v_pct := v_rule.prem_percentage;
    v_min := v_rule.prem_minimum;
  ELSIF v_tier = 'standard' THEN
    v_pct := v_rule.stand_percentage;
    v_min := v_rule.stand_minimum;
  ELSE
    v_pct := v_rule.free_percentage;
    v_min := v_rule.free_minimum;
  END IF;

  v_pct := coalesce(v_pct, 0.0);
  v_min := coalesce(v_min, 0.0);

  -- Calling fees are percentage-only and require 4 decimal places of precision ($0.0001/min)
  IF p_item = 'intelcallfee' THEN
    v_fee := round((p_base_amount * v_pct) / 100.0, 4);
  ELSE
    v_fee := round(greatest((p_base_amount * v_pct) / 100.0, v_min), 2);
  END IF;

  RETURN v_fee;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_esim_offer_price(p_wholesale_price numeric, p_user_id uuid DEFAULT auth.uid())
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tier TEXT;
  v_fee  NUMERIC;
BEGIN
  IF p_wholesale_price IS NULL OR p_wholesale_price <= 0 THEN
    RETURN 0.00;
  END IF;

  v_tier := public.resolve_account_commerce_benefit(p_user_id);
  v_fee := public.resolve_app_fee('esimofferfee', v_tier, p_wholesale_price);

  IF v_fee IS NULL OR v_fee = 0 THEN
    v_fee := CASE v_tier
      WHEN 'premium'  THEN round(p_wholesale_price * 0.05, 2)
      WHEN 'standard' THEN round(p_wholesale_price * 0.07, 2)
      ELSE round(p_wholesale_price * 0.10, 2)
    END;
  END IF;

  RETURN round(p_wholesale_price + v_fee, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_line_entitlement(p_sim_line_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_line              RECORD;
  v_plan              TEXT;
  v_protection        TEXT;
  v_effective_tier    TEXT := 'free';
  v_is_paid           BOOLEAN := false;
  v_is_premium        BOOLEAN := false;
  v_is_expired        BOOLEAN := false;
  v_auto_eligible     BOOLEAN := false;
BEGIN
  SELECT id, user_id, plan_type, protection_tier, plan_expires_at, status
  INTO v_line
  FROM public.sim_lines
  WHERE id = p_sim_line_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'found', false,
      'effective_tier', 'free',
      'is_paid', false,
      'is_premium', false,
      'automation_eligible', false
    );
  END IF;

  v_plan := lower(coalesce(v_line.plan_type, 'free'));
  v_protection := lower(coalesce(v_line.protection_tier, 'basic'));

  IF v_plan = 'free' OR (v_plan = '' AND v_protection = 'basic') THEN
    v_effective_tier := 'free';
    v_is_paid := false;
    v_is_premium := false;
    v_is_expired := false;
    v_auto_eligible := false;
  ELSE
    IF v_line.plan_expires_at IS NOT NULL AND v_line.plan_expires_at <= now() THEN
      v_effective_tier := 'free';
      v_is_paid := false;
      v_is_premium := false;
      v_is_expired := true;
      v_auto_eligible := false;
    ELSE
      IF v_plan = 'premium' OR v_protection = 'premium' THEN
        v_effective_tier := 'premium';
        v_is_paid := true;
        v_is_premium := true;
        v_auto_eligible := true;
      ELSE
        v_effective_tier := 'standard';
        v_is_paid := true;
        v_is_premium := false;
        v_auto_eligible := false;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'sim_line_id', v_line.id,
    'user_id', v_line.user_id,
    'plan_type', v_line.plan_type,
    'protection_tier', v_line.protection_tier,
    'effective_tier', v_effective_tier,
    'is_paid', v_is_paid,
    'is_premium', v_is_premium,
    'is_expired', v_is_expired,
    'expires_at', v_line.plan_expires_at,
    'automation_eligible', v_auto_eligible
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.settle_call_wallet_hold(p_hold_id uuid, p_actual_cost numeric, p_description text DEFAULT 'International Call'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_hold RECORD;
  v_wallet RECORD;
  v_balance_after NUMERIC;
  v_txn_id UUID;
  v_alloc RECORD;
  v_to_consume NUMERIC;
  v_lot_consume NUMERIC;
BEGIN
  -- Lock hold
  SELECT * INTO v_hold
  FROM public.wallet_holds
  WHERE id = p_hold_id
  FOR UPDATE;

  IF v_hold.id IS NULL THEN
    RAISE EXCEPTION 'Hold not found: %', p_hold_id;
  END IF;

  -- Idempotency check: if already captured, return existing transaction
  IF v_hold.status = 'captured' THEN
    SELECT id INTO v_txn_id
    FROM public.wallet_transactions
    WHERE reference_id = 'hold_' || p_hold_id::text;
    IF v_txn_id IS NOT NULL THEN
      RETURN v_txn_id;
    END IF;
  END IF;

  IF v_hold.status = 'released' THEN
    RETURN NULL;
  END IF;

  IF v_hold.status != 'active' THEN
    RAISE EXCEPTION 'Cannot settle hold in status: %', v_hold.status;
  END IF;

  -- If actual cost is zero or negative (e.g. unanswered call), release the hold completely
  IF p_actual_cost IS NULL OR p_actual_cost <= 0 THEN
    UPDATE public.wallet_holds
    SET status = 'released',
        released_at = now(),
        updated_at = now()
    WHERE id = p_hold_id;
    RETURN NULL;
  END IF;

  -- Cap actual cost to held amount if rounding exceeds
  IF p_actual_cost > v_hold.amount THEN
    p_actual_cost := v_hold.amount;
  END IF;

  -- Lock wallet
  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE id = v_hold.wallet_id
  FOR UPDATE;

  IF v_wallet.balance < p_actual_cost THEN
    RAISE EXCEPTION 'Invariant violation: wallet balance % is less than actual cost %', v_wallet.balance, p_actual_cost;
  END IF;

  v_balance_after := v_wallet.balance - p_actual_cost;

  -- Update wallet balance
  UPDATE public.wallets
  SET balance = v_balance_after,
      total_spent = total_spent + p_actual_cost,
      updated_at = now()
  WHERE id = v_wallet.id;

  -- Consume funding lots FIFO only up to p_actual_cost
  v_to_consume := p_actual_cost;
  FOR v_alloc IN
    SELECT * FROM public.wallet_hold_allocations
    WHERE hold_id = p_hold_id
    ORDER BY id ASC
  LOOP
    EXIT WHEN v_to_consume <= 0;
    v_lot_consume := LEAST(v_alloc.amount, v_to_consume);

    UPDATE public.wallet_funding_lots
    SET remaining_amount = remaining_amount - v_lot_consume,
        status = CASE WHEN remaining_amount - v_lot_consume = 0 THEN 'fully_consumed' ELSE status END,
        updated_at = now()
    WHERE id = v_alloc.lot_id;

    v_to_consume := v_to_consume - v_lot_consume;
  END LOOP;

  -- Mark hold captured
  UPDATE public.wallet_holds
  SET status = 'captured',
      captured_at = now(),
      updated_at = now()
  WHERE id = p_hold_id;

  -- Record ledger transaction
  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, balance_before, balance_after,
    description, reference_id, status, metadata, created_at
  ) VALUES (
    v_wallet.id, v_hold.user_id, 'call_debit', p_actual_cost, v_wallet.balance, v_balance_after,
    COALESCE(p_description, 'International Call'),
    'hold_' || p_hold_id::text,
    'completed',
    jsonb_build_object(
      'hold_id', p_hold_id,
      'order_type', v_hold.order_type,
      'order_reference_id', v_hold.order_reference_id,
      'held_amount', v_hold.amount,
      'settled_amount', p_actual_cost
    ) || COALESCE(p_metadata, '{}'::jsonb),
    now()
  ) RETURNING id INTO v_txn_id;

  RETURN v_txn_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.settle_line_verification_attempt(p_attempt_id uuid, p_outcome text, p_carrier_name text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_attempt RECORD;
  v_channel_label TEXT;
  v_desc TEXT;
BEGIN
  SELECT * INTO v_attempt
  FROM public.line_verification_attempts
  WHERE id = p_attempt_id
  FOR UPDATE;

  IF v_attempt.id IS NULL THEN
    RAISE EXCEPTION 'Attempt not found: %', p_attempt_id;
  END IF;

  IF v_attempt.status = 'terminal' THEN
    RETURN jsonb_build_object('success', true, 'status', 'terminal', 'outcome', v_attempt.outcome);
  END IF;

  IF p_outcome = 'succeeded' THEN
    -- 1. Settle Funds or Allowance
    IF v_attempt.funding_kind = 'wallet' AND v_attempt.wallet_hold_id IS NOT NULL THEN
      PERFORM public.capture_wallet_hold(
        v_attempt.wallet_hold_id,
        'verification_debit',
        'Real Live Verification (' || UPPER(v_attempt.method) || ')',
        jsonb_build_object('attempt_id', p_attempt_id, 'sim_line_id', v_attempt.sim_line_id)
      );
    ELSIF v_attempt.funding_kind = 'annual_allowance' THEN
      UPDATE public.line_verification_allowances
      SET consumed_attempt_id = p_attempt_id,
          reserved_attempt_id = NULL,
          updated_at = now()
      WHERE sim_line_id = v_attempt.sim_line_id
        AND (reserved_attempt_id = p_attempt_id OR consumed_attempt_id IS NULL);
    END IF;

    -- 2. Update SIM line verification & health score
    UPDATE public.sim_lines
    SET verification_status = 'verified',
        health_score = 100,
        carrier_verified_at = now(),
        detected_operator_name = COALESCE(p_carrier_name, detected_operator_name),
        updated_at = now()
    WHERE id = v_attempt.sim_line_id;

    -- 3. Log Activity
    v_channel_label := CASE WHEN v_attempt.method = 'sms' THEN 'SMS DLR Handshake' ELSE 'Missed Call Ring' END;
    v_desc := 'SIM line live verified active via ' || v_channel_label;
    IF p_carrier_name IS NOT NULL AND p_carrier_name <> '' THEN
      v_desc := v_desc || ' on ' || p_carrier_name;
    END IF;
    v_desc := v_desc || '. Health optimized to 100.';

    INSERT INTO public.line_activity_log (
      sim_line_id, user_id, event_type, description, created_at
    ) VALUES (
      v_attempt.sim_line_id, v_attempt.user_id, 'health_update', v_desc, now()
    );

    -- 4. Mark attempt terminal succeeded
    UPDATE public.line_verification_attempts
    SET status = 'terminal',
        outcome = 'succeeded',
        settlement_status = CASE 
          WHEN funding_kind = 'wallet' THEN 'captured'
          WHEN funding_kind = 'annual_allowance' THEN 'consumed'
          ELSE 'no_charge'
        END,
        carrier_name = COALESCE(p_carrier_name, carrier_name),
        completed_at = now(),
        updated_at = now()
    WHERE id = p_attempt_id;

  ELSE
    -- FAILED or INCONCLUSIVE: Release hold / allowance
    IF v_attempt.funding_kind = 'wallet' AND v_attempt.wallet_hold_id IS NOT NULL THEN
      PERFORM public.release_wallet_hold(
        v_attempt.wallet_hold_id,
        COALESCE(p_error_message, 'Verification check was unsuccessful')
      );
    ELSIF v_attempt.funding_kind = 'annual_allowance' THEN
      UPDATE public.line_verification_allowances
      SET reserved_attempt_id = NULL,
          updated_at = now()
      WHERE sim_line_id = v_attempt.sim_line_id
        AND reserved_attempt_id = p_attempt_id;
    END IF;

    UPDATE public.line_verification_attempts
    SET status = 'terminal',
        outcome = p_outcome,
        settlement_status = 'released',
        error_message = p_error_message,
        completed_at = now(),
        updated_at = now()
    WHERE id = p_attempt_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'attempt_id', p_attempt_id,
    'outcome', p_outcome,
    'settlement_status', CASE WHEN p_outcome = 'succeeded' THEN 'captured_or_consumed' ELSE 'released' END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.settle_successful_execution(p_execution_id uuid, p_provider_tx_id text, p_hold_id uuid DEFAULT NULL::uuid, p_pin_code text DEFAULT NULL::text, p_pin_serial text DEFAULT NULL::text, p_redeem_instructions text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_exec RECORD;
  v_hold_id UUID := p_hold_id;
  v_txn_id UUID := NULL;
  v_hold RECORD;
BEGIN
  -- 1. Lock execution row
  SELECT * INTO v_exec
  FROM public.topup_executions
  WHERE id = p_execution_id
  FOR UPDATE;

  IF v_exec.id IS NULL THEN
    RAISE EXCEPTION 'Execution not found: %', p_execution_id;
  END IF;

  -- If execution is already success, return idempotently
  IF v_exec.status = 'success' THEN
    SELECT id INTO v_txn_id
    FROM public.wallet_transactions
    WHERE reference_id = 'hold_' || COALESCE(v_exec.wallet_hold_id, p_hold_id)::text;

    RETURN jsonb_build_object(
      'success', true,
      'idempotent', true,
      'execution_id', v_exec.id,
      'status', 'success',
      'txn_id', v_txn_id
    );
  END IF;

  -- Determine hold_id
  IF v_hold_id IS NULL THEN
    v_hold_id := v_exec.wallet_hold_id;
  END IF;

  -- 2. If hold_id is present, capture the hold
  IF v_hold_id IS NOT NULL THEN
    SELECT * INTO v_hold
    FROM public.wallet_holds
    WHERE id = v_hold_id;

    IF v_hold.id IS NOT NULL THEN
      IF v_hold.status = 'active' THEN
        v_txn_id := public.capture_wallet_hold(
          p_hold_id => v_hold_id,
          p_txn_type => 'topup_debit',
          p_description => 'Auto-Refill: ' || COALESCE(v_exec.execution_type, 'refill'),
          p_metadata => jsonb_build_object(
            'execution_id', v_exec.id,
            'sim_line_id', v_exec.sim_line_id,
            'provider_tx_id', p_provider_tx_id
          ) || COALESCE(p_metadata, '{}'::jsonb)
        );
      ELSIF v_hold.status = 'captured' THEN
        SELECT id INTO v_txn_id
        FROM public.wallet_transactions
        WHERE reference_id = 'hold_' || v_hold_id::text;
      ELSE
        RAISE EXCEPTION 'Hold % is in invalid status for capture: %', v_hold_id, v_hold.status;
      END IF;
    END IF;
  END IF;

  -- 3. Update execution status atomically
  UPDATE public.topup_executions
  SET status = 'success',
      reloadly_transaction_id = p_provider_tx_id,
      wallet_hold_id = COALESCE(v_hold_id, wallet_hold_id),
      pin_code = COALESCE(p_pin_code, pin_code),
      pin_serial = COALESCE(p_pin_serial, pin_serial),
      redeem_instructions = COALESCE(p_redeem_instructions, redeem_instructions),
      executed_at = COALESCE(executed_at, now()),
      completed_at = now(),
      failure_reason = NULL,
      updated_at = now()
  WHERE id = p_execution_id;

  RETURN jsonb_build_object(
    'success', true,
    'execution_id', p_execution_id,
    'provider_tx_id', p_provider_tx_id,
    'hold_id', v_hold_id,
    'wallet_txn_id', v_txn_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_fn_apply_plan_tier_from_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_plan text;
  v_owner_id uuid;
BEGIN
  -- Only apply when kind = 'plan' and sim_line_id is provided
  IF NEW.kind = 'plan' AND NEW.sim_line_id IS NOT NULL THEN
    v_plan := NEW.metadata ->> 'plan';

    -- Whitelist valid plan types
    IF v_plan IS NOT NULL AND v_plan IN ('standard', 'premium', 'basic', 'free') THEN
      -- Verify NEW.user_id owns NEW.sim_line_id
      SELECT user_id INTO v_owner_id
      FROM public.sim_lines
      WHERE id = NEW.sim_line_id;

      IF v_owner_id IS NOT NULL AND (NEW.user_id IS NULL OR v_owner_id = NEW.user_id) THEN
        BEGIN
          UPDATE public.sim_lines
          SET plan_type = v_plan,
              plan_expires_at = NOW() + INTERVAL '1 year',
              updated_at = NOW()
          WHERE id = NEW.sim_line_id;
        EXCEPTION WHEN OTHERS THEN
          INSERT INTO public.system_alerts (kind, message, details, created_at)
          VALUES (
            'plan_tier_update_failed',
            'Failed to update plan_type for sim_line ' || NEW.sim_line_id::text,
            jsonb_build_object('error', SQLERRM, 'payment_id', NEW.id),
            NOW()
          );
        END;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_fn_award_referral_points()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_sim_line_id uuid;
  v_line_owner_id uuid;
  v_referred_by text;
  v_referrer_id uuid;
  v_daily_cap int := 10;
  v_today_points int := 0;
  v_current_balance int := 0;
  v_inserted_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'wallet_transactions' THEN
    IF NEW.type <> 'plan_fee_debit' OR NEW.sim_line_id IS NULL THEN
      RETURN NEW;
    END IF;
    v_sim_line_id := NEW.sim_line_id;
  ELSIF TG_TABLE_NAME = 'plan_payments' THEN
    IF NEW.kind <> 'plan' OR NEW.sim_line_id IS NULL THEN
      RETURN NEW;
    END IF;
    v_sim_line_id := NEW.sim_line_id;
  ELSE
    RETURN NEW;
  END IF;

  SELECT user_id INTO v_line_owner_id
  FROM public.sim_lines
  WHERE id = v_sim_line_id;

  IF v_line_owner_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT referred_by INTO v_referred_by
  FROM public.profiles
  WHERE id = v_line_owner_id;

  IF v_referred_by IS NULL OR length(trim(v_referred_by)) = 0 THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_referrer_id
  FROM public.profiles
  WHERE UPPER(referral_code) = UPPER(TRIM(v_referred_by));

  IF v_referrer_id IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    SELECT config_value::int INTO v_daily_cap
    FROM public.system_configs
    WHERE config_key = 'REFERRAL_DAILY_POINT_CAP';
  EXCEPTION WHEN OTHERS THEN
    v_daily_cap := 10;
  END;
  IF v_daily_cap IS NULL OR v_daily_cap <= 0 THEN
    v_daily_cap := 10;
  END IF;

  SELECT COALESCE(SUM(points), 0) INTO v_today_points
  FROM public.referral_points
  WHERE referrer_id = v_referrer_id
    AND created_at >= date_trunc('day', now());

  IF v_today_points >= v_daily_cap THEN
    INSERT INTO public.system_alerts (kind, message, details)
    VALUES (
      'referral_cap_hit',
      'Daily referral point cap hit for referrer ' || v_referrer_id::text,
      jsonb_build_object(
        'referrer_id', v_referrer_id,
        'referred_user_id', v_line_owner_id,
        'sim_line_id', v_sim_line_id,
        'daily_cap', v_daily_cap,
        'today_points', v_today_points
      )
    );
    RETURN NEW;
  END IF;

  INSERT INTO public.referral_points (referrer_id, referred_user_id, sim_line_id, points, source)
  VALUES (v_referrer_id, v_line_owner_id, v_sim_line_id, 1, TG_TABLE_NAME)
  ON CONFLICT (sim_line_id) DO NOTHING
  RETURNING id INTO v_inserted_id;

  IF v_inserted_id IS NOT NULL THEN
    SELECT COALESCE(SUM(p.points), 0) - COALESCE((
      SELECT SUM(r.points_spent) FROM public.referral_redemptions r WHERE r.user_id = v_referrer_id
    ), 0) INTO v_current_balance
    FROM public.referral_points p
    WHERE p.referrer_id = v_referrer_id;

    INSERT INTO public.notifications (user_id, category, title, body)
    VALUES (
      v_referrer_id,
      'referral_reward',
      'Referral Point Earned! 🎁',
      'You earned 1 point for a friend''s SIM line subscription! Your current balance is ' || v_current_balance::text || ' points.'
    );
  END IF;

  RETURN NEW;
END;
$function$

