 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_on   text;
  v_skip text;
  v_pat  text;
BEGIN
  IF NEW.status <> 'failed' OR OLD.status = 'failed' THEN
    RETURN NEW;
  END IF;

  -- Guard for v2 auto-refill resilience: v2 executions handle replacement and
  -- failover directly within the worker engine, retaining the same occurrence identity.
  -- This prevents legacy trigger from spawning duplicate topup_executions rows.
  IF COALESCE(NEW.engine_version, 1) >= 2 THEN
    RETURN NEW;
  END IF;

  BEGIN
    SELECT config_value INTO v_on FROM public.system_configs WHERE config_key = 'SUPPLIER_RETRY_ENABLED';
  EXCEPTION WHEN OTHERS THEN v_on := NULL;
  END;
  IF lower(COALESCE(v_on, 'false')) <> 'true' THEN
    RETURN NEW;
  END IF;

  -- Do not retry a failure that will fail identically at any supplier.
  BEGIN
    SELECT config_value INTO v_skip FROM public.system_configs WHERE config_key = 'SUPPLIER_RETRY_SKIP_REASONS';
  EXCEPTION WHEN OTHERS THEN v_skip := NULL;
  END;

  IF NEW.failure_reason IS NOT NULL AND COALESCE(v_skip, '') <> '' THEN
    FOREACH v_pat IN ARRAY string_to_array(v_skip, ',') LOOP
      IF btrim(v_pat) <> '' AND position(lower(btrim(v_pat)) in lower(NEW.failure_reason)) > 0 THEN
        RETURN NEW;
      END IF;
    END LOOP;
  END IF;

  -- Never let a failover error abort the failure write itself: the row must end
  -- up 'failed' even if the retry cannot be built.
  BEGIN
    PERFORM public.retry_execution_at_next_supplier(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.system_alerts (kind, message, details, created_at)
    VALUES ('supplier_failover_failed',
            'Failover could not queue a retry for execution ' || NEW.id::text,
            jsonb_build_object('error', SQLERRM), now());
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_fn_log_topup_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_type TEXT;
  v_metadata JSONB;
BEGIN
  -- Guard: If sim_line does not exist (e.g. being deleted in the current transaction),
  -- skip inserting into line_activity_log to avoid FK constraint violation.
  IF NEW.sim_line_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.sim_lines WHERE id = NEW.sim_line_id
  ) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_event_type := CASE 
      WHEN NEW.retry_of IS NOT NULL THEN 'topup_retry_queued'
      ELSE 'topup_requested'
    END;

    v_metadata := jsonb_build_object(
      'amount', NEW.amount,
      'base_cost_usd', NEW.base_cost_usd,
      'execution_id', NEW.id,
      'execution_type', NEW.execution_type,
      'funding_kind', NEW.funding_kind,
      'provider', COALESCE(NEW.api_provider, 'zendit'),
      'offer_id', NEW.offer_id,
      'refill_channel', NEW.refill_channel
    );

    INSERT INTO public.line_activity_log (
      sim_line_id, user_id, event_type, description, metadata, created_at
    ) VALUES (
      NEW.sim_line_id, NEW.user_id, v_event_type, NULL, v_metadata, clock_timestamp()
    );

  ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF NEW.status = 'success' THEN
      v_event_type := 'topup_success';
      v_metadata := jsonb_build_object(
        'amount', NEW.amount,
        'execution_id', NEW.id,
        'execution_type', NEW.execution_type,
        'funding_kind', NEW.funding_kind,
        'provider', COALESCE(NEW.api_provider, 'zendit'),
        'transaction_id', NEW.reloadly_transaction_id,
        'refill_channel', NEW.refill_channel
      );
    ELSIF NEW.status = 'failed' THEN
      v_event_type := 'topup_failed';
      v_metadata := jsonb_build_object(
        'amount', NEW.amount,
        'execution_id', NEW.id,
        'execution_type', NEW.execution_type,
        'funding_kind', NEW.funding_kind,
        'provider', COALESCE(NEW.api_provider, 'zendit'),
        'failure_reason', COALESCE(NEW.failure_reason, 'Execution failed'),
        'refill_channel', NEW.refill_channel
      );
    ELSIF NEW.status = 'refunded' THEN
      v_event_type := 'topup_refunded';
      v_metadata := jsonb_build_object(
        'amount', NEW.amount,
        'execution_id', NEW.id,
        'execution_type', NEW.execution_type,
        'funding_kind', NEW.funding_kind,
        'refund_reason', COALESCE(NEW.failure_reason, 'Wallet refunded')
      );
    ELSIF NEW.status = 'cancelled' THEN
      v_event_type := 'topup_cancelled';
      v_metadata := jsonb_build_object(
        'amount', NEW.amount,
        'execution_id', NEW.id,
        'execution_type', NEW.execution_type,
        'funding_kind', NEW.funding_kind
      );
    ELSE
      RETURN NEW;
    END IF;

    INSERT INTO public.line_activity_log (
      sim_line_id, user_id, event_type, description, metadata, created_at
    ) VALUES (
      NEW.sim_line_id, NEW.user_id, v_event_type, NULL, v_metadata, clock_timestamp()
    );
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.route_topup_execution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE 
  v_gateway VARCHAR; 
  v_api_provider text;
BEGIN
  IF NEW.status IN ('pending', 'pending_payment', 'routing') THEN
    -- Priority 1: If offer_id is set and api_provider is not set, resolve from offer catalog cache
    IF NEW.api_provider IS NULL AND NEW.offer_id IS NOT NULL THEN
      SELECT api_provider INTO v_api_provider
      FROM public.provider_offers_cache
      WHERE offer_id = NEW.offer_id
      LIMIT 1;

      IF v_api_provider IS NULL THEN
        SELECT provider_code INTO v_api_provider
        FROM public.provider_offers
        WHERE offer_code = NEW.offer_id
        LIMIT 1;
      END IF;
    END IF;

    -- Priority 2: Carrier's primary provider from carrier_provider_map
    IF v_api_provider IS NULL THEN
      SELECT m.provider INTO v_api_provider
      FROM public.sim_lines sl
      JOIN public.carriers ca ON sl.carrier_id = ca.id
      LEFT JOIN public.carrier_provider_map m ON m.carrier_id = ca.id AND m.is_primary
      WHERE sl.id = NEW.sim_line_id;
    END IF;

    -- Resolve fulfillment gateway
    SELECT ca.fulfillment_gateway INTO v_gateway
    FROM public.sim_lines sl
    JOIN public.carriers ca ON sl.carrier_id = ca.id
    WHERE sl.id = NEW.sim_line_id;

    IF NEW.fulfillment_gateway IS NULL THEN
      IF v_gateway IS NULL THEN
        SELECT config_value INTO v_gateway FROM public.system_configs
         WHERE config_key = 'ACTIVE_FULFILLMENT_METHOD' LIMIT 1;
        IF v_gateway IS NULL THEN v_gateway := 'MANUAL'; END IF;
      END IF;

      IF v_gateway = 'TASKER_SCRIPT' AND NEW.execution_type = 'refill_instant' THEN 
        v_gateway := 'API'; 
      END IF;

      IF v_gateway = 'TASKER_SCRIPT' AND NOT EXISTS (
        SELECT 1 FROM public.sim_lines sl2
        JOIN public.refill_scripts rs ON rs.carrier_id = sl2.carrier_id
        WHERE sl2.id = NEW.sim_line_id AND rs.is_enabled
          AND NEW.execution_type = ANY (rs.allowed_execution_types)) THEN
        v_gateway := 'API';
      END IF;

      NEW.fulfillment_gateway := v_gateway;
    END IF;

    -- Always populate api_provider if not already set
    NEW.api_provider := COALESCE(NEW.api_provider, v_api_provider);

    -- Initialize attempted_providers as empty array if null
    IF NEW.attempted_providers IS NULL THEN
      NEW.attempted_providers := ARRAY[]::text[];
    END IF;

    IF NEW.execution_type = 'refill_instant' AND NEW.status = 'pending' THEN 
      NEW.status := 'routing'; 
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

